// ---------------------------------------------------------------------------------------------
// Issue / problem codes raised by the data path (copy-data)
// ---------------------------------------------------------------------------------------------

pub const CODE_ROW_TOO_LARGE: &str = "ROW_TOO_LARGE";
pub const CODE_DATA_WARNINGS: &str = "DATA_WARNINGS";
pub const CODE_ROWS_SKIPPED: &str = "ROWS_SKIPPED";
pub const CODE_BINARY_ATTR_UNDECODABLE: &str = "BINARY_ATTR_UNDECODABLE";
pub const CODE_UNMAPPABLE: &str = "UNMAPPABLE_CHARS";
pub const CODE_VERIFY_MISMATCH: &str = "VERIFY_MISMATCH";
pub const CODE_TARGET_LOCK_TIMEOUT: &str = "TARGET_LOCK_TIMEOUT";
pub const CODE_DDL_WARNING: &str = "DDL_WARNING";
pub const CODE_DDL_SUBSTITUTED: &str = "DDL_SUBSTITUTED";
pub const CODE_DEPENDENCY_FAILED: &str = "DEPENDENCY_FAILED";
pub const CODE_INVALID_DATE: &str = "INVALID_DATE";
pub const CODE_FK_ORPHANS: &str = "FK_ORPHANS";
pub const CODE_SKIPPED_DIFFERS: &str = "SKIPPED_DIFFERS";
pub const CODE_SERVER_ROLLBACK_PENDING: &str = "SERVER_ROLLBACK_PENDING";
/// A write-ahead checkpoint could not be stored: the action was not taken.
pub const CODE_CHECKPOINT_FAILED: &str = "CHECKPOINT_FAILED";
/// A floor-rule sequence whose target value could not be read was left as is.
pub const CODE_SEQUENCE_FLOOR_UNREADABLE: &str = "SEQUENCE_FLOOR_UNREADABLE";
/// A MySQL ENUM column holds the error value `''` (index 0) of a non-strict server, which a
/// strict target refuses (`enum_error: null` loads NULL instead).
pub const CODE_ENUM_ERROR_VALUE: &str = "ENUM_ERROR_VALUE";
/// The `ValueFix` code of an ENUM error value loaded as NULL.
pub const FIX_ENUM_ERROR_NULL: &str = "ENUM_ERROR_NULL";
/// PG sources before 12 print floats with `extra_float_digits = 3` differently from 12+:
/// the table's checksum is not computed (row counts still are).
pub const CODE_CHECKSUM_NOT_APPLICABLE: &str = "CHECKSUM_NOT_APPLICABLE";

/// A data-path failure carrying a copy code (`DATA_WARNINGS`, `ROW_TOO_LARGE`, ...): a `QUERY`
/// error whose code slot holds the copy code instead of a SQLSTATE.
pub fn copy_fail(code: &str, msg: impl Into<String>) -> CoreError {
    CoreError::Query { code: Some(code.to_string()), msg: msg.into() }
}

/// The copy code of an error made by [`copy_fail`] (SQLSTATEs have no underscore).
pub fn fail_code(e: &CoreError) -> Option<&str> {
    match e {
        CoreError::Query { code: Some(c), .. } if c.contains('_') && c.chars().all(|ch| ch.is_ascii_uppercase() || ch == '_' || ch.is_ascii_digit()) => Some(c.as_str()),
        _ => None,
    }
}

/// The wire payload of a copy error: redacted message, the copy code as detail.
pub fn error_payload(e: &CoreError) -> crate::error::ErrorPayload {
    let mut p = e.to_payload();
    p.message = redact_values(&p.message);
    if let Some(code) = fail_code(e) {
        p.detail = Some(code.to_string());
    }
    p.detail = p.detail.map(|d| redact_values(&d));
    p
}

// ---------------------------------------------------------------------------------------------
// Job state
// ---------------------------------------------------------------------------------------------

struct TableEntry {
    p: CopyTableProgress,
    started: Option<Instant>,
}

struct ProgressState {
    seq: u64,
    phase: CopyPhase,
    plan: Option<CopyPlan>,
    tables: Vec<TableEntry>,
    index: HashMap<String, usize>,
    items_total: u32,
    items_done: u32,
    items_failed: u32,
    items_skipped: u32,
    tables_done: u32,
    tables_failed: u32,
    result: Option<CopyResult>,
    /// `<identity key>/<database>` of the target, for the in-process lease registry.
    target_key: Option<String>,
    /// `<identity key>/<database>` of the source (`SOURCE_BEING_WRITTEN`).
    source_key: Option<String>,
}

/// Process-side state of one copy job, held by `JobEntry.copy`.
pub struct CopyJob {
    info: Mutex<CopyJobInfo>,
    st: Mutex<ProgressState>,
}

impl std::fmt::Debug for CopyJob {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("CopyJob").field("info", &self.info()).finish_non_exhaustive()
    }
}

impl CopyJob {
    pub fn new(info: CopyJobInfo) -> CopyJob {
        let phase = info.phase;
        CopyJob {
            info: Mutex::new(info),
            st: Mutex::new(ProgressState {
                seq: 0,
                phase,
                plan: None,
                tables: Vec::new(),
                index: HashMap::new(),
                items_total: 0,
                items_done: 0,
                items_failed: 0,
                items_skipped: 0,
                tables_done: 0,
                tables_failed: 0,
                result: None,
                target_key: None,
                source_key: None,
            }),
        }
    }

    /// `JobSummary.copy`.
    pub fn info(&self) -> CopyJobInfo {
        self.info.lock().unwrap().clone()
    }

    /// Replace the summary (phase / table counters change while the job runs).
    pub fn set_info(&self, info: CopyJobInfo) {
        *self.info.lock().unwrap() = info;
    }

    pub fn run_id(&self) -> String {
        self.info.lock().unwrap().run_id.clone()
    }

    fn sync_info(&self, st: &ProgressState) {
        let mut info = self.info.lock().unwrap();
        info.phase = st.phase;
        info.tables_total = st.tables.len() as u32;
        info.tables_done = st.tables_done;
        info.tables_failed = st.tables_failed;
    }

    /// The plan the job runs; the table entries (`loads`: item id, estimated rows) start
    /// `pending`; `items_total` counts the items that will execute.
    pub fn set_plan(&self, plan: &CopyPlan, loads: &[(String, Option<u64>)], items_total: u32) {
        let mut st = self.st.lock().unwrap();
        st.plan = Some(plan.clone());
        st.seq += 1;
        let seq = st.seq;
        st.tables = loads
            .iter()
            .map(|(id, est)| TableEntry {
                p: CopyTableProgress {
                    seq,
                    item_id: id.clone(),
                    state: CopyItemState::Pending,
                    rows_read: 0,
                    rows_written: 0,
                    bytes: 0,
                    est_rows: *est,
                    rate_rows_per_sec: 0.0,
                    elapsed_ms: None,
                    method: None,
                    error: None,
                },
                started: None,
            })
            .collect();
        st.index = st.tables.iter().enumerate().map(|(i, t)| (t.p.item_id.clone(), i)).collect();
        st.items_total = items_total;
        self.sync_info(&st);
    }

    pub fn plan(&self) -> Option<CopyPlan> {
        self.st.lock().unwrap().plan.clone()
    }

    pub fn set_phase(&self, phase: CopyPhase) {
        let mut st = self.st.lock().unwrap();
        if st.phase != phase {
            st.phase = phase;
            st.seq += 1;
            self.sync_info(&st);
        }
    }

    pub fn phase(&self) -> CopyPhase {
        self.st.lock().unwrap().phase
    }

    /// Update one table entry (no-op for unknown ids); bumps `seq`.
    pub fn update_table(&self, item_id: &str, f: impl FnOnce(&mut CopyTableProgress)) {
        let mut st = self.st.lock().unwrap();
        let Some(&i) = st.index.get(item_id) else {
            return;
        };
        st.seq += 1;
        let seq = st.seq;
        let entry = &mut st.tables[i];
        let before = entry.p.state;
        f(&mut entry.p);
        if entry.started.is_none() && matches!(entry.p.state, CopyItemState::Creating | CopyItemState::Loading) {
            entry.started = Some(Instant::now());
        }
        if let Some(t0) = entry.started {
            let ms = t0.elapsed().as_millis() as u64;
            entry.p.elapsed_ms = Some(ms);
            entry.p.rate_rows_per_sec = if ms > 0 { entry.p.rows_written as f64 * 1000.0 / ms as f64 } else { 0.0 };
        }
        entry.p.seq = seq;
        let after = entry.p.state;
        if before != after {
            let terminal =
                |s: CopyItemState| matches!(s, CopyItemState::Done | CopyItemState::Skipped | CopyItemState::Failed | CopyItemState::Cancelled | CopyItemState::Planned);
            if !terminal(before) {
                match after {
                    CopyItemState::Done | CopyItemState::Skipped | CopyItemState::Planned => st.tables_done += 1,
                    CopyItemState::Failed | CopyItemState::Cancelled => st.tables_failed += 1,
                    _ => {}
                }
            }
            self.sync_info(&st);
        }
    }

    /// Rows read / written and bytes of a table (added).
    pub fn add_rows(&self, item_id: &str, read: u64, written: u64, bytes: u64) {
        self.update_table(item_id, |p| {
            p.rows_read += read;
            p.rows_written += written;
            p.bytes += bytes;
        });
    }

    /// Count a finished item (any kind).
    pub fn item_finished(&self, state: CopyItemState) {
        let mut st = self.st.lock().unwrap();
        st.seq += 1;
        match state {
            CopyItemState::Failed | CopyItemState::Cancelled => st.items_failed += 1,
            CopyItemState::Skipped => st.items_skipped += 1,
            _ => st.items_done += 1,
        }
    }

    /// The full progress of this job.
    pub fn progress(&self, job_id: &str) -> CopyProgress {
        let run_id = self.run_id();
        let st = self.st.lock().unwrap();
        CopyProgress {
            job_id: job_id.to_string(),
            run_id,
            seq: st.seq,
            phase: st.phase,
            items_total: st.items_total,
            items_done: st.items_done,
            items_failed: st.items_failed,
            items_skipped: st.items_skipped,
            tables_total: st.tables.len() as u32,
            tables_done: st.tables_done,
            tables: st.tables.iter().map(|t| t.p.clone()).collect(),
            full: true,
        }
    }

    /// Current entry of one table.
    pub fn table(&self, item_id: &str) -> Option<CopyTableProgress> {
        let st = self.st.lock().unwrap();
        st.index.get(item_id).map(|&i| st.tables[i].p.clone())
    }

    pub fn set_result(&self, result: CopyResult) {
        let mut st = self.st.lock().unwrap();
        st.result = Some(result);
        st.seq += 1;
    }

    pub fn result(&self) -> Option<CopyResult> {
        self.st.lock().unwrap().result.clone()
    }

    pub fn set_keys(&self, source: Option<String>, target: Option<String>) {
        let mut st = self.st.lock().unwrap();
        st.source_key = source;
        st.target_key = target;
    }

    /// (`source key`, `target key`) of the lease registry.
    pub fn keys(&self) -> (Option<String>, Option<String>) {
        let st = self.st.lock().unwrap();
        (st.source_key.clone(), st.target_key.clone())
    }
}

// ---------------------------------------------------------------------------------------------
// Redaction (5.2)
// ---------------------------------------------------------------------------------------------

/// Words that, right before a single-quoted literal, mark it as a name (kept) rather than a
/// value (redacted): "for key 'k'", "for column 'c'", "Table 'db.t' doesn't exist", ...
const NAME_WORDS: &[&str] = &[
    "key",
    "column",
    "table",
    "database",
    "schema",
    "index",
    "constraint",
    "field",
    "function",
    "procedure",
    "trigger",
    "view",
    "user",
    "variable",
    "engine",
    "set",
    "collation",
    "charset",
    "partition",
    "tablespace",
    "sequence",
    "event",
    "role",
    "plugin",
    "file",
    "storage",
];

fn redact_single_quotes(msg: &str) -> String {
    let b = msg.as_bytes();
    let mut out = String::with_capacity(msg.len());
    let mut i = 0;
    let mut last = 0;
    while i < b.len() {
        if b[i] != b'\'' {
            i += 1;
            continue;
        }
        // Find the closing quote ('' and \' are escapes).
        let start = i;
        let mut j = i + 1;
        let mut closed = None;
        while j < b.len() {
            match b[j] {
                b'\\' => j += 2,
                b'\'' if j + 1 < b.len() && b[j + 1] == b'\'' => j += 2,
                b'\'' => {
                    closed = Some(j);
                    break;
                }
                _ => j += 1,
            }
        }
        let Some(end) = closed else {
            break;
        };
        let before = msg[..start].trim_end();
        let word = before.rsplit(|c: char| !(c.is_alphanumeric() || c == '_')).next().unwrap_or("").to_ascii_lowercase();
        let is_name = NAME_WORDS.contains(&word.as_str()) || before.ends_with('`') || end == start + 1;
        if !is_name {
            out.push_str(&msg[last..=start]);
            out.push('…');
            last = end;
        }
        i = end + 1;
    }
    out.push_str(&msg[last..]);
    out
}

/// Replace data values in server messages with '…' before anything leaves the writer (5.2):
/// MySQL single-quoted literals except key / column / table names in known shapes
/// ("Duplicate entry '…' for key 'k'", "Incorrect string value: '…' for column 'c' at row 5"),
/// PostgreSQL `Key (cols)=(…)` value lists, `Failing row contains (…)`, the value of
/// `CONTEXT: COPY t, line 5, column c: "…"` and `for type t: "…"`; the code, column and line
/// stay.
pub fn redact_values(msg: &str) -> String {
    use std::sync::OnceLock;
    static RES: OnceLock<Vec<(regex::Regex, &'static str)>> = OnceLock::new();
    let res = RES.get_or_init(|| {
        vec![
            (regex::Regex::new(r"\)=\(.*?\)(\s+(?:already exists|is not present|is still referenced|conflicts))").unwrap(), ")=(…)$1"),
            (regex::Regex::new(r"(?m)(Failing row contains )\(.*\)").unwrap(), "$1(…)"),
            (regex::Regex::new(r#"(?m)(COPY [^,\n]+, line \d+, column [^:\n]+: )"[^\n]*""#).unwrap(), "$1\"…\""),
            (regex::Regex::new(r#"(?m)(COPY [^,\n]+, line \d+: )"[^\n]*""#).unwrap(), "$1\"…\""),
            (regex::Regex::new(r#"(for type [A-Za-z0-9_ ]+: )"[^"\n]*""#).unwrap(), "$1\"…\""),
            (regex::Regex::new(r#"(value too long for type [^\n]*?: )"[^"\n]*""#).unwrap(), "$1\"…\""),
        ]
    });
    let mut s = redact_single_quotes(msg);
    for (re, rep) in res {
        s = re.replace_all(&s, *rep).into_owned();
    }
    s
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn redacts_mysql_samples() {
        assert_eq!(redact_values("Duplicate entry '홍길동-42' for key 'users.uniq_name'"), "Duplicate entry '…' for key 'users.uniq_name'");
        assert_eq!(redact_values("Incorrect string value: '\\xF0\\x9F\\x98\\x80' for column 'name' at row 5"), "Incorrect string value: '…' for column 'name' at row 5");
        assert_eq!(redact_values("Data truncated for column 'price' at row 3"), "Data truncated for column 'price' at row 3");
        assert_eq!(redact_values("Incorrect integer value: 'abc' for column 'id' at row 1"), "Incorrect integer value: '…' for column 'id' at row 1");
        assert_eq!(redact_values("Incorrect date value: '2004-02-31' for column 'd' at row 9"), "Incorrect date value: '…' for column 'd' at row 9");
        assert_eq!(redact_values("Table 'shop.orders' doesn't exist"), "Table 'shop.orders' doesn't exist");
        assert_eq!(redact_values("Truncated incorrect DOUBLE value: 'it''s'"), "Truncated incorrect DOUBLE value: '…'");
        assert_eq!(redact_values("Field 'x' doesn't have a default value"), "Field 'x' doesn't have a default value");
    }

    #[test]
    fn redacts_postgres_samples() {
        assert_eq!(
            redact_values("duplicate key value violates unique constraint \"t_pkey\"\nDETAIL: Key (id, name)=(5, Kim (Jr.)) already exists."),
            "duplicate key value violates unique constraint \"t_pkey\"\nDETAIL: Key (id, name)=(…) already exists."
        );
        assert_eq!(
            redact_values("insert or update on table \"o\" violates foreign key constraint \"o_fk\"\nDETAIL: Key (customer_id)=(77) is not present in table \"c\"."),
            "insert or update on table \"o\" violates foreign key constraint \"o_fk\"\nDETAIL: Key (customer_id)=(…) is not present in table \"c\"."
        );
        assert_eq!(
            redact_values("invalid input syntax for type integer: \"abc\"\nCONTEXT: COPY orders, line 5, column qty: \"abc\""),
            "invalid input syntax for type integer: \"…\"\nCONTEXT: COPY orders, line 5, column qty: \"…\""
        );
        assert_eq!(
            redact_values("new row for relation \"t\" violates check constraint \"c\"\nDETAIL: Failing row contains (1, secret, 3)."),
            "new row for relation \"t\" violates check constraint \"c\"\nDETAIL: Failing row contains (…)."
        );
        assert_eq!(redact_values("relation \"public.t\" does not exist"), "relation \"public.t\" does not exist");
    }

    #[test]
    fn copy_codes_round_trip() {
        let e = copy_fail(CODE_DATA_WARNINGS, "2 warnings: Data truncated for column 'c' at row 1, value 'x'");
        assert_eq!(fail_code(&e), Some(CODE_DATA_WARNINGS));
        assert_eq!(fail_code(&CoreError::query_with_code("23505", "dup")), None);
        let p = error_payload(&copy_fail(CODE_DATA_WARNINGS, "Incorrect integer value: 'abc' for column 'id' at row 1"));
        assert_eq!(p.detail.as_deref(), Some(CODE_DATA_WARNINGS));
        assert!(p.message.contains("'…'") && !p.message.contains("abc"));
    }

    #[test]
    fn job_progress_bumps_seq_and_counts() {
        let job = CopyJob::new(CopyJobInfo {
            run_id: "r1".into(),
            target_conn_id: "t".into(),
            target_conn_name: "T".into(),
            source_database: "a".into(),
            target_database: "b".into(),
            phase: CopyPhase::Plan,
            tables_total: 0,
            tables_done: 0,
            tables_failed: 0,
            dry_run: false,
        });
        assert_eq!(job.progress("j").tables.len(), 0);
        let plan_stub = crate::copy::testkit::empty_plan(CopyFamily::Sqlite);
        job.set_plan(&plan_stub, &[("table:\"a\"".into(), Some(10)), ("table:\"b\"".into(), None)], 3);
        let s0 = job.progress("j").seq;
        job.add_rows("table:\"a\"", 5, 5, 100);
        let p = job.progress("j");
        assert!(p.seq > s0);
        let a = p.tables.iter().find(|t| t.item_id == "table:\"a\"").unwrap();
        assert_eq!((a.rows_read, a.rows_written, a.bytes), (5, 5, 100));
        assert_eq!(a.seq, p.seq);
        job.update_table("table:\"a\"", |t| t.state = CopyItemState::Done);
        job.update_table("table:\"b\"", |t| t.state = CopyItemState::Failed);
        let info = job.info();
        assert_eq!((info.tables_total, info.tables_done, info.tables_failed), (2, 1, 1));
        job.update_table("missing", |t| t.rows_read = 1);
    }
}
